#include <string_view>

#define COLOR_LIST(X) \
    X(red)            \
    X(green)          \
    X(blue)           \
    X(amber)

enum class Color
{
#define X(name) name,
    COLOR_LIST(X)
#undef X
};

constexpr std::string_view toString(Color color)
{
    switch (color)
    {
#define X(name) case Color::name: return #name;
        COLOR_LIST(X)
#undef X
    }
    return "?";
}

#define X(name) +1
inline constexpr int colorCount{ 0 COLOR_LIST(X) };
#undef X

unitTests:
static_assert(colorCount == 4);
static_assert(static_cast<int>(Color::red) == 0 && static_cast<int>(Color::amber) == 3);
static_assert(toString(Color::green) == "green", "toString must be constexpr");

TEST("names") { CHECK_EQ(toString(Color::red), "red"); CHECK_EQ(toString(Color::blue), "blue"); CHECK_EQ(toString(Color::amber), "amber"); }
TEST("the helper macro is cleaned up afterwards") {
#ifdef X
    CHECK(false);
#else
    CHECK(true);
#endif
}

